// analysis: exhaustive prefix splitter for the repaired E11 support search.
//
// For one orbit branch, enumerate all partial supports up to a split depth under
// the same sound constraints used by cover_bitset_dfs: cap<=5 Wang rows
// with saturation propagation, optional cover Wang rows with one-row residual
// capacity pruning, and optional mixed lower rows.  At each live split node it
// prints a force/exclude subproblem line covering the remaining subtree in the
// fixed increasing-order search: force = chosen prefix, exclude = all domain
// points below next_min not already forced (plus earlier orbit classes inherited
// when replaying with --branch-none).  The list is a coverage-preserving frontier
// if the split run completes.

#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <sstream>
#include <string>
#include <vector>

static constexpr int MAXP=255, WORDS=4; static bool bit4(const uint64_t w[WORDS],int p){return (w[p>>6]>>(p&63))&1ULL;} static void setbit4(uint64_t w[WORDS],int p){w[p>>6]|=1ULL<<(p&63);} static void clrbit4(uint64_t w[WORDS],int p){w[p>>6]&=~(1ULL<<(p&63));} static int pop4(const uint64_t w[WORDS]){return __builtin_popcountll(w[0])+__builtin_popcountll(w[1])+__builtin_popcountll(w[2])+__builtin_popcountll(w[3]);}
struct Row{uint8_t cap=0,dim=0;uint16_t res=0;uint64_t word[WORDS]={0,0,0,0};}; struct Cut{uint8_t K=0;uint64_t w1[WORDS]={0,0,0,0};uint64_t w2[WORDS]={0,0,0,0};uint8_t coeff[256]{};}; struct Branch{int id=-1,rep=0;uint64_t forbid[WORDS]={0,0,0,0};};
static bool load_rows(const std::string&p,std::vector<Row>&rows){if(p.empty())return true;std::ifstream in(p,std::ios::binary);if(!in){std::cerr<<"open fail "<<p<<"\n";return false;}char m[8];in.read(m,8);if(!in||std::memcmp(m,"E11WANG1",8)!=0){std::cerr<<"bad row magic\n";return false;}uint32_t n;in.read((char*)&n,4);rows.resize(n);for(uint32_t i=0;i<n;i++){in.read((char*)&rows[i].cap,1);in.read((char*)&rows[i].dim,1);in.read((char*)&rows[i].res,2);for(int w=0;w<WORDS;w++)in.read((char*)&rows[i].word[w],8);}return bool(in);} 
static bool load_cuts(const std::string&p,std::vector<Cut>&cuts){if(p.empty())return true;std::ifstream in(p,std::ios::binary);if(!in){std::cerr<<"open cuts fail\n";return false;}char m[8];in.read(m,8);if(!in||std::memcmp(m,"MIXCUT1\0",8)!=0){std::cerr<<"bad cut magic\n";return false;}uint32_t n;in.read((char*)&n,4);cuts.resize(n);for(uint32_t i=0;i<n;i++){uint8_t fl;uint16_t rs;in.read((char*)&cuts[i].K,1);in.read((char*)&fl,1);in.read((char*)&rs,2);for(int w=0;w<WORDS;w++)in.read((char*)&cuts[i].w1[w],8);for(int w=0;w<WORDS;w++)in.read((char*)&cuts[i].w2[w],8);for(int p=1;p<=MAXP;p++)cuts[i].coeff[p]=bit4(cuts[i].w2,p)?2:(bit4(cuts[i].w1,p)?1:0);}return bool(in);} 
static std::vector<std::vector<uint32_t>> point_rows(const std::vector<Row>&rows){std::vector<std::vector<uint32_t>>pr(256);for(uint32_t i=0;i<rows.size();i++)for(int p=1;p<=MAXP;p++)if(bit4(rows[i].word,p))pr[p].push_back(i);return pr;}
static std::vector<Branch> branches(){const int reps[8]={1,4,5,8,10,40,42,80};const std::vector<std::vector<int>> members={{1,2,3},{4,32,36},{5,6,7,33,34,35,37,38,39},{8,9,12,13,16,18,20,22,24,27,28,31,64,65,72,73,96,97,108,109,128,130,144,146,160,162,180,182,192,195,216,219,224,227,252,255},{10,11,14,15,17,19,21,23,25,26,29,30,66,67,74,75,98,99,110,111,129,131,145,147,161,163,181,183,193,194,217,218,225,226,253,254},{40,41,44,45,48,50,52,54,56,59,60,63,68,69,76,77,100,101,104,105,132,134,148,150,164,166,176,178,196,199,220,223,228,231,248,251},{42,43,46,47,49,51,53,55,57,58,61,62,70,71,78,79,102,103,106,107,133,135,149,151,165,167,177,179,197,198,221,222,229,230,249,250},{80,81,82,83,84,85,86,87,88,89,90,91,92,93,94,95,112,113,114,115,116,117,118,119,120,121,122,123,124,125,126,127,136,137,138,139,140,141,142,143,152,153,154,155,156,157,158,159,168,169,170,171,172,173,174,175,184,185,186,187,188,189,190,191,200,201,202,203,204,205,206,207,208,209,210,211,212,213,214,215,232,233,234,235,236,237,238,239,240,241,242,243,244,245,246,247}};std::vector<Branch>out;uint64_t f[WORDS]={0,0,0,0};for(int i=0;i<8;i++){Branch b;b.id=i;b.rep=reps[i];for(int w=0;w<WORDS;w++)b.forbid[w]=f[w];out.push_back(b);for(int p:members[i])setbit4(f,p);}return out;}
static std::string list_json(const std::vector<int>&v){std::ostringstream o;o<<"[";for(size_t i=0;i<v.size();i++){if(i)o<<",";o<<v[i];}o<<"]";return o.str();}
struct Search{const std::vector<Row>&rows;const std::vector<std::vector<uint32_t>>&pr;const std::vector<Row>&cov;const std::vector<std::vector<uint32_t>>&cpr;const std::vector<Cut>&cuts;int target,split_depth,cover_min_depth;double limit;std::chrono::steady_clock::time_point start;std::vector<uint8_t>cnt,ccnt;std::vector<int16_t>lhs;uint64_t dom[WORDS],initial_forbid[WORDS];std::vector<int>chosen;std::ofstream out;uint64_t calls=0,frontier=0,shortage=0,cover_prunes=0,mixed_prunes=0,overcap=0,cover_over=0,saturated=0,sat_removed=0;bool timeout=false;std::array<uint64_t,32> nodes{};Search(const std::vector<Row>&r,const std::vector<std::vector<uint32_t>>&p,const std::vector<Row>&cr,const std::vector<std::vector<uint32_t>>&cp,const std::vector<Cut>&cu,int t,int sd,int cmd,double lim,const std::string&outp):rows(r),pr(p),cov(cr),cpr(cp),cuts(cu),target(t),split_depth(sd),cover_min_depth(cmd),limit(lim),cnt(r.size(),0),ccnt(cr.size(),0),lhs(cu.size(),0){out.open(outp);}
 bool timed()const{return limit>0&&std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()>=limit;} void full_domain(){dom[0]=dom[1]=dom[2]=dom[3]=~0ULL;dom[0]&=~1ULL;} bool in_dom(int p)const{return bit4(dom,p);} int avail_from(int minp)const{int c=0;for(int p=minp;p<=MAXP;p++)if(in_dom(p))c++;return c;} void future_words(int minp,uint64_t f[WORDS])const{for(int w=0;w<WORDS;w++)f[w]=dom[w];if(minp>1)for(int p=1;p<minp&&p<=MAXP;p++)clrbit4(f,p);} bool mixed_possible(int minp,int need){if(cuts.empty())return true;uint64_t fut[WORDS];future_words(minp,fut);for(size_t i=0;i<cuts.size();i++){uint64_t a1[WORDS],a2[WORDS];for(int w=0;w<WORDS;w++){a1[w]=fut[w]&cuts[i].w1[w];a2[w]=fut[w]&cuts[i].w2[w];}int c2=pop4(a2),c1=pop4(a1);int take2=std::min(c2,need),take1=std::min(c1,need-take2);if(lhs[i]+2*take2+take1<cuts[i].K){mixed_prunes++;return false;}}return true;} bool cover_possible(int minp,int need){if(cov.empty())return true;int depth=chosen.size();if(!(need==0||depth>=cover_min_depth))return true;uint64_t fut[WORDS];future_words(minp,fut);int avail=pop4(fut);for(size_t i=0;i<cov.size();i++){int u=(int)cov[i].cap-(int)ccnt[i];if(u>=need)continue;if(u<0){cover_prunes++;return false;}uint64_t a[WORDS];for(int w=0;w<WORDS;w++)a[w]=fut[w]&cov[i].word[w];int outside=avail-pop4(a);if(u+outside<need){cover_prunes++;return false;}}return true;}
 bool try_select(int q,std::vector<uint32_t>&t,std::vector<uint32_t>&ct,uint64_t old[WORDS]){for(int w=0;w<WORDS;w++)old[w]=dom[w];if(!in_dom(q))return false;for(uint32_t ri:pr[q])if((int)cnt[ri]+1>rows[ri].cap){overcap++;return false;}for(uint32_t ri:cpr[q])if((int)ccnt[ri]+1>cov[ri].cap){cover_over++;return false;}clrbit4(dom,q);for(uint32_t ri:pr[q]){cnt[ri]++;t.push_back(ri);}for(uint32_t ri:cpr[q]){ccnt[ri]++;ct.push_back(ri);}for(size_t i=0;i<cuts.size();i++)lhs[i]+=cuts[i].coeff[q];for(uint32_t ri:t)if(cnt[ri]==rows[ri].cap){saturated++;int before=pop4(dom);for(int w=0;w<WORDS;w++)dom[w]&=~rows[ri].word[w];int after=pop4(dom);if(before>after)sat_removed+=before-after;}return true;} void undo(int q,const std::vector<uint32_t>&t,const std::vector<uint32_t>&ct,const uint64_t old[WORDS]){for(size_t i=0;i<cuts.size();i++)lhs[i]-=cuts[i].coeff[q];for(auto it=t.rbegin();it!=t.rend();++it)cnt[*it]--;for(auto it=ct.rbegin();it!=ct.rend();++it)ccnt[*it]--;for(int w=0;w<WORDS;w++)dom[w]=old[w];}
 void emit_frontier(int minp){frontier++;std::vector<int> excl;for(int p=1;p<minp;p++)if(!std::binary_search(chosen.begin(),chosen.end(),p))excl.push_back(p); // includes earlier orbit classes and skipped points
  out<<"{\"force\":"<<list_json(chosen)<<",\"exclude_lt_next\":"<<list_json(excl)<<",\"next_min\":"<<minp<<",\"need\":"<<(target-(int)chosen.size())<<",\"avail\":"<<avail_from(minp)<<"}\n";}
 void dfs(int minp){if(timeout)return;if((calls++&0x3FFFULL)==0&&timed()){timeout=true;return;}int d=chosen.size();if(d<32)nodes[d]++;if(d==split_depth){emit_frontier(minp);return;}if(d==target){emit_frontier(MAXP+1);return;}int need=target-d;if(avail_from(minp)<need){shortage++;return;}if(!cover_possible(minp,need))return;if(!mixed_possible(minp,need))return;for(int q=minp;q<=MAXP;q++){if(MAXP-q+1<need)break;if(!in_dom(q))continue;if(avail_from(q)<need)break;std::vector<uint32_t>t,ct;uint64_t old[WORDS];if(try_select(q,t,ct,old)){chosen.push_back(q);dfs(q+1);chosen.pop_back();undo(q,t,ct,old);}if(timeout)return;}}
 bool run(const Branch&br){nodes.fill(0);full_domain();for(int w=0;w<WORDS;w++){initial_forbid[w]=br.forbid[w];dom[w]&=~br.forbid[w];}for(const auto&r:rows)if(r.cap==0)for(int w=0;w<WORDS;w++)dom[w]&=~r.word[w];start=std::chrono::steady_clock::now();std::vector<uint32_t>t,ct;uint64_t old[WORDS];if(!try_select(br.rep,t,ct,old))return false;chosen.push_back(br.rep);dfs(br.rep+1);return true;}}
;
int main(int argc,char**argv){std::string cons,covers,cuts,outp,summary;int branch=-1,target=19,split=10,cover_min=10;double lim=300;for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--constraints"&&i+1<argc)cons=argv[++i];else if(a=="--cover-constraints"&&i+1<argc)covers=argv[++i];else if(a=="--cuts"&&i+1<argc)cuts=argv[++i];else if(a=="--output"&&i+1<argc)outp=argv[++i];else if(a=="--summary"&&i+1<argc)summary=argv[++i];else if(a=="--branch"&&i+1<argc)branch=std::stoi(argv[++i]);else if(a=="--target"&&i+1<argc)target=std::stoi(argv[++i]);else if(a=="--split-depth"&&i+1<argc)split=std::stoi(argv[++i]);else if(a=="--cover-min-depth"&&i+1<argc)cover_min=std::stoi(argv[++i]);else if(a=="--timeout"&&i+1<argc)lim=std::stod(argv[++i]);else{std::cerr<<"bad arg "<<a<<"\n";return 2;}}if(cons.empty()||outp.empty()||branch<0){std::cerr<<"usage...\n";return 2;}std::vector<Row>rows,cov;std::vector<Cut>cutv;if(!load_rows(cons,rows)||!load_rows(covers,cov)||!load_cuts(cuts,cutv))return 1;auto pr=point_rows(rows),cpr=point_rows(cov);auto brs=branches();Search S(rows,pr,cov,cpr,cutv,target,split,cover_min,lim,outp);bool ok=S.run(brs[branch]);double el=std::chrono::duration<double>(std::chrono::steady_clock::now()-S.start).count();std::ostringstream js;js<<"{\"schema\":\"s0908_cover_exhaust_prefix_v1\",\"branch\":"<<branch<<",\"rep\":"<<brs[branch].rep<<",\"target\":"<<target<<",\"split_depth\":"<<split<<",\"complete\":"<<(ok&&!S.timeout?"true":"false")<<",\"timeout\":"<<(S.timeout?"true":"false")<<",\"elapsed_sec\":"<<std::fixed<<std::setprecision(6)<<el<<",\"calls\":"<<S.calls<<",\"frontier_nodes\":"<<S.frontier<<",\"global_shortage\":"<<S.shortage<<",\"overcap\":"<<S.overcap<<",\"cover_overcap\":"<<S.cover_over<<",\"cover_prunes\":"<<S.cover_prunes<<",\"mixed_prunes\":"<<S.mixed_prunes<<",\"saturated\":"<<S.saturated<<",\"sat_removed\":"<<S.sat_removed<<",\"node_count_by_depth\":[";for(int i=0;i<=split&&i<32;i++){if(i)js<<",";js<<S.nodes[i];}js<<"],\"frontier_path\":\""<<outp<<"\"}";std::cout<<js.str()<<"\n";if(!summary.empty()){std::ofstream f(summary);f<<js.str()<<"\n";}return 0;}
